	ops, balancer, instances := newNodeOpsTest(t)
	n := netbirdRollout{fence: ops.fence}
	spec, addresses := ops.fence.spec()
	if err := ops.fence.fence(t.Context(), balancer, 3, *spec, "ctl-2", addresses["ctl-2"], 0, netbirdHold); err != nil {
