func (l *fenceLease) ReadNetBirdState(context.Context) (authority.LogEntry, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.netbird.Sequence == 0 {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	entry := l.netbird
	entry.Payload = slices.Clone(entry.Payload)
	return entry, nil
}

func (l *fenceLease) CommitNetBirdState(ctx context.Context, epoch uint64, operation string, expected uint64, wire []byte) (uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	if l.lost || epoch != 3 {
		return 0, authority.ErrFenced
	}
	if l.netbird.Sequence != expected {
		return 0, authority.ErrConflict
	}
	l.netbird = authority.LogEntry{Epoch: epoch, Sequence: expected + 1, OperationID: operation, Payload: slices.Clone(wire)}
	return l.netbird.Sequence, nil
}

func saveNetBirdTestRecord(ctx context.Context, n *netbirdRollout, epoch uint64, record network.Record) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	next := state
	if state.Record.ID != record.ID || state.Record.Node != record.Node {
		next.Command = network.Command{}
	}
	next.Record = record
	return n.commitStateAt(ctx, epoch, &state, next)
}

func saveNetBirdTestAdmission(ctx context.Context, n *netbirdRollout, epoch uint64, record network.Record) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	return n.saveRecordAt(ctx, epoch, &state, record)
}

func saveNetBirdTestCommand(ctx context.Context, n *netbirdRollout, epoch uint64, node string, command network.Command) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	return n.sendAt(ctx, epoch, &state, node, command)
}

type fenceLease struct {
	mu   sync.Mutex
	lost bool
	// lose, when set, loses the lease after that many guards.
	lose, guards int
	netbird      authority.LogEntry
}

func (l *fenceLease) Current() authority.Snapshot {
	l.mu.Lock()
	defer l.mu.Unlock()
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true, Leader: !l.lost, Epoch: 3, Revision: 1, ExpiresAt: time.Now().Add(time.Hour)}
}

func (l *fenceLease) Guard(_ context.Context, epoch uint64) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.guards++
	if l.lose > 0 && l.guards >= l.lose {
		l.lost = true
	}
	if l.lost || epoch != 3 {
		return authority.ErrFenced
	}
	return nil
}

type netbirdStateReader interface {
	ReadNetBirdState(context.Context) (authority.LogEntry, error)
}

type netbirdStateStore interface {
	netbirdStateReader
	CommitNetBirdState(context.Context, uint64, string, uint64, []byte) (uint64, error)
}

// Journal and command share one revision, so a stale tick cannot publish a
// command after another controller advances the transaction.
type netbirdState struct {
	Record   network.Record  `json:"record"`
	Command  network.Command `json:"command"`
	Revision uint64          `json:"-"`
}

func netbirdCommandAllowed(record network.Record, action string) bool {
	if record.RecoveryComplete {
		return false
	}
	switch record.Phase {
	case "install", "confirm":
		return action == record.Phase
	case "rollback", "rollback-check":
		return action == "rollback"
	case "failed":
		return action == "rollback" && (record.RollbackRequired == nil || *record.RollbackRequired)
	default:
		return false
	}
}

func (state netbirdState) commandFor(node string) (network.Command, bool, error) {
	command := state.Command
	if state.Record.Node != node || command.ID == "" || !netbirdCommandAllowed(state.Record, command.Action) {
		return network.Command{}, false, nil
	}
	if command.Transaction != state.Record.ID || command.ID != network.CommandID(state.Record.ID, command.Action) ||
		network.Hash(command.Target) != network.Hash(state.Record.Target) {
		return network.Command{}, false, errors.New("NetBird command does not match the active transaction")
	}
	return command, true, nil
}

func readNetBirdState(ctx context.Context, reader netbirdStateReader) (netbirdState, error) {
	entry, err := reader.ReadNetBirdState(ctx)
	if errors.Is(err, authority.ErrNotFound) {
		return netbirdState{}, nil
	}
	if err != nil {
		return netbirdState{}, err
	}
	return decodeNetBirdState(entry)
}

func decodeNetBirdState(entry authority.LogEntry) (netbirdState, error) {
	var state netbirdState
	if entry.Sequence == 0 || entry.Epoch == 0 {
		return state, errors.New("invalid NetBird journal revision")
	}
	if err := json.Unmarshal(entry.Payload, &state, json.RejectUnknownMembers(true)); err != nil {
		return state, err
	}
	if (state.Record.ID != "" || state.Record.Phase != "" || state.Record.Node != "") && !entityid.Valid(state.Record.ID) {
		return state, errors.New("invalid NetBird journal identity")
	}
	state.Revision = entry.Sequence
	return state, nil
}

func (n *netbirdRollout) state(ctx context.Context) (netbirdState, error) {
	reader, ok := n.fence.fencer.(netbirdStateReader)
	if !ok {
		return netbirdState{}, errors.New("NetBird requires an authority journal reader")
	}
	return readNetBirdState(ctx, reader)
}

func (n *netbirdRollout) commitStateAt(ctx context.Context, epoch uint64, state *netbirdState, next netbirdState) error {
	store, ok := n.fence.fencer.(netbirdStateStore)
	if !ok {
		return errors.New("NetBird requires an authority journal writer")
	}
	if (next.Record.ID != "" || next.Record.Phase != "" || next.Record.Node != "") && !entityid.Valid(next.Record.ID) {
		return errors.New("invalid NetBird journal identity")
	}
	original, err := json.Marshal(*state, json.Deterministic(true))
	if err != nil {
		return err
	}
	wire, err := json.Marshal(next, json.Deterministic(true))
	if err != nil {
		return err
	}
	expected, operation := state.Revision, entityid.New()
	for attempt := range 3 {
		revision, err := store.CommitNetBirdState(ctx, epoch, operation, expected, wire)
		if err == nil {
			next.Revision = revision
			*state = next
			return nil
		}
		if !errors.Is(err, authority.ErrConflict) || attempt == 2 {
			return err
		}
		current, err := readNetBirdState(ctx, store)
		if err != nil {
			return err
		}
		currentWire, err := json.Marshal(current, json.Deterministic(true))
		if err != nil {
			return err
		}
		// Issuance changes only the revision; a changed intent invalidates
		// the original tick's health, drain and return decisions.
		if !bytes.Equal(original, currentWire) {
			return authority.ErrConflict
		}
		expected = current.Revision
	}
	return authority.ErrConflict
}

func (n *netbirdRollout) sendAt(ctx context.Context, epoch uint64, state *netbirdState, node string, command network.Command) error {
	if state.Revision == 0 || state.Record.Node != node || state.Record.ID != command.Transaction ||
		command.ID != network.CommandID(state.Record.ID, command.Action) || network.Hash(command.Target) != network.Hash(state.Record.Target) ||
		!netbirdCommandAllowed(state.Record, command.Action) {
		return errors.New("NetBird command does not match its journal snapshot")
	}
	next := *state
	next.Command = command
	return n.commitStateAt(ctx, epoch, state, next)
}

func (n *netbirdRollout) loadIntent(ctx context.Context, key string, value any) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	if state.Revision == 0 {
		return os.ErrNotExist
	}
	var intent any = state.Record
	if key != netbirdRecordKey {
		if key != "netbird.command."+state.Record.Node {
			return os.ErrNotExist
		}
		command, found, err := state.commandFor(state.Record.Node)
		if err != nil {
			return err
		}
		if !found {
			return os.ErrNotExist
		}
		intent = command
	}
	wire, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	return json.Unmarshal(wire, value, json.RejectUnknownMembers(true))
}

func (r *specRegistry) netbird() *cellspec.NetBird {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.current.NetBird
}

// A spec amendment cannot abandon a node already drained or changed. Finish
// its persisted target before using the new pin or disabling management.
func (n *netbirdRollout) target(ctx context.Context) (*cellspec.NetBird, error) {
	var record network.Record
	if err := n.load(ctx, netbirdRecordKey, &record); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	if record.ID != "" && record.Phase != "done" && (record.Phase != "failed" || !record.RecoveryComplete) {
		return &cellspec.NetBird{Pin: record.Target.Pin, Enrollment: record.Target.Enrollment}, nil
	}
	return n.services.netbird(), nil
}

type netbirdRollout struct {
	cell             string
	fence            *releaseFence
	services         *specRegistry
	nodes            *nodeOps
	key              ed25519.PrivateKey
	cfg              Config
	fleet            oci.Fleet
	artifacts        jetstream.ObjectStore
	conn             *nats.Conn
	runtime          *natscell.Runtime
	managedAddresses map[string]string
	observed         time.Time
	artifactMu       sync.Mutex
	verifiedMetadata [2][]byte
}

func (n *netbirdRollout) load(ctx context.Context, key string, value any) error {
	if key == netbirdRecordKey || strings.HasPrefix(key, "netbird.command.") {
		return n.loadIntent(ctx, key, value)
	}
	return n.fence.loadJSON(ctx, key, value)
}

func (n *netbirdRollout) saveAt(ctx context.Context, epoch uint64, key string, value any) error {
	if !strings.HasPrefix(key, "netbird.status.") {
		return errors.New("NetBird intent requires a conditional authority commit")
	}
	wire, err := json.Marshal(value)
	if err != nil {
		return err
	}
	if err := n.fence.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = n.fence.kv.Put(ctx, key, wire)
	return err
}

func (n *netbirdRollout) saveRecordAt(ctx context.Context, epoch uint64, state *netbirdState, record network.Record) error {
	if record.Phase == "drain" && len(record.Fence) == 0 {
		spec, addresses := n.addresses()
		if spec == nil || addresses[record.Node] == "" {
			return errors.New("NetBird admission requires a release fence and verified OCI address")
		}
		if err := netbirdOCIAddress(addresses[record.Node]); err != nil {
			return err
		}
		wire, err := json.Marshal(spec)
		if err != nil {
			return err
		}
		record.Fence, record.OCIAddress = wire, addresses[record.Node]
	}
	next := *state
	if next.Record.ID != record.ID || next.Record.Node != record.Node {
		next.Command = network.Command{}
	}
	next.Record = record
	if !netbirdCommandAllowed(record, next.Command.Action) {
		next.Command = network.Command{}
	}
	return n.commitStateAt(ctx, epoch, state, next)
}

func (n *netbirdRollout) Exchange(ctx context.Context, registration host.Registration, status network.Status) ([]byte, error) {
	if err := status.Validate(); err != nil {
		return nil, err
	}
	pin, err := n.target(ctx)
	if err != nil {
		return nil, err
	}
	if pin == nil {
		return nil, nil
	}
	epoch, err := n.fence.leading(ctx)
	if err != nil {
		return nil, err
	}
	if !status.ObservedAt.IsZero() && time.Since(status.ObservedAt) < 15*time.Second && time.Until(status.ObservedAt) < 2*time.Second {
		if len(status.Version) > 32 || len(status.IP) > 64 || len(status.DNS) > 255 || len(status.ActionID) > 160 || len(status.Error) > 512 ||
			status.AppliedTargetHash != "" && !client.SHA256Pattern.MatchString(status.AppliedTargetHash) || status.Missing && status.Version != "" {
			return nil, errors.New("invalid NetBird status")
		}
		if err := n.saveAt(ctx, epoch, "netbird.status."+registration.Node, status); err != nil {
			return nil, err
		}
	}
	state, err := n.state(ctx)
	if err != nil {
		return nil, err
	}
	command, found, err := state.commandFor(registration.Node)
	if err != nil || !found {
		return nil, err
	}
	wire, err := json.Marshal(command)
	if err != nil {
		return nil, err
	}
	now := time.Now().UTC()
	step, err := protocol.SignEnvelope(wire, protocol.EnvelopeScope{Region: n.cell, Kind: "netbird.step", Actor: registration.Node,
		OperationID: command.ID, Epoch: epoch, Generation: command.Generation}, now, now.Add(local.StepLifetime), n.key)
	if err != nil {
		return nil, err
	}
	reply, err := json.Marshal(step)
	if err != nil {
		return nil, err
	}
	// Issuance has the same durable order as phase changes and authority
	// handoff; a superseded snapshot must never yield a signed command.
	if err := n.commitStateAt(ctx, epoch, &state, state); err != nil {
		return nil, err
	}
	return reply, nil
}

