type netbirdConflictingLease struct {
	*fenceLease
	attempts int
	fence    bool
}

func (l *netbirdConflictingLease) CommitNetBirdState(ctx context.Context, epoch uint64, operation string, expected uint64, wire []byte) (uint64, error) {
	l.attempts++
	if l.fence && l.attempts > 1 {
		l.mu.Lock()
		l.lost = true
		l.mu.Unlock()
		return l.fenceLease.CommitNetBirdState(ctx, epoch, operation, expected, wire)
	}
	return 0, authority.ErrConflict
}

issuance_race.text:
type netbirdIssuanceRace struct {
	*fenceLease
	armed        atomic.Bool
	beforeCommit func() error
}

func (l *netbirdIssuanceRace) CommitNetBirdState(ctx context.Context, epoch uint64, operation string, expected uint64, wire []byte) (uint64, error) {
	if l.armed.Swap(false) {
		if err := l.beforeCommit(); err != nil {
			return 0, err
		}
	}
	return l.fenceLease.CommitNetBirdState(ctx, epoch, operation, expected, wire)
}

journal_reconciler.text:
func (status Status) Validate() error {
	if status.Pending != "" && !entityid.Valid(status.Pending) || status.ActionID != "" && !entityid.Valid(status.ActionID) {
		return errors.New("invalid NetBird status identity")
	}
	return nil
}

type Command struct {
	Generation  uint64 `json:"generation"`
	ID          string `json:"id"`
	Transaction string `json:"transaction"`
	Action      string `json:"action"`
	Target      Target `json:"target"`
}

// CommandID gives retries of one action the same independently scoped ID.
func CommandID(transaction, action string) string {
	return entityid.Derive("netbird-command", transaction, action)
}

type Record struct {
	ID                string    `json:"id"`
	Node              string    `json:"node"`
	Previous          string    `json:"previous"`
	Target            Target    `json:"target"`
	PinHash           string    `json:"pin_hash"`
	Phase             string    `json:"phase"`
	RollbackRequired  *bool     `json:"rollback_required,omitempty"`
	RecoveryComplete  bool      `json:"recovery_complete,omitempty"`
	RecoveryReturning bool      `json:"recovery_returning,omitempty"`
	Deadline          time.Time `json:"deadline"`
	StartedAt         time.Time `json:"started_at"`
	Reason            string    `json:"reason,omitempty"`
	// Admission survives pin, grant and fence amendments until recovery.
	Fence      jsontext.Value `json:"fence,omitempty"`
	OCIAddress string         `json:"oci_address,omitempty"`
}

// The store and every effect must be guarded by the same authority epoch.
// A failed rollback holds the cell until an operator repairs its access path.
type Reconciler struct {
	Load      func(context.Context) (Record, error)
	Save      func(context.Context, Record) error
	Status    func(context.Context, string) (Status, error)
	Preflight func(context.Context, string) error
	Drain     func(context.Context, string) error
	Healthy   func(context.Context, string, Status, time.Time) error
	Return    func(context.Context, string) error
	Send      func(context.Context, string, Command) error
	Now       func() time.Time
}

func Hash(target Target) string {
	wire, _ := json.Marshal(target, json.Deterministic(true))
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

func (r *Reconciler) Tick(ctx context.Context, target Target, nodes []string) error {
	currentTime := func() time.Time {
		if r.Now != nil {
			return r.Now().UTC()
		}
		return time.Now().UTC()
	}
	now := currentTime()
	record, err := r.Load(ctx)
	if err != nil {
		return err
	}
	if record.Phase != "" && !entityid.Valid(record.ID) {
		return errors.New("invalid NetBird rollout identity")
	}
	if record.RecoveryReturning && !record.RecoveryComplete {
		// Fence an interrupted return before any status or health gate.
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		record.RecoveryReturning = false
		if err := r.Save(ctx, record); err != nil {
			return err
		}
	}
	returnNode := func() error {
		record.RecoveryReturning = true
		if err := r.Save(ctx, record); err != nil {
			return err
		}
		if err := r.Return(ctx, record.Node); err != nil {
			// Return may clear backend flags before its health check fails.
			if drainErr := r.Drain(ctx, record.Node); drainErr != nil {
				return errors.Join(err, drainErr)
			}
			record.RecoveryReturning = false
			return errors.Join(err, r.Save(ctx, record))
		}
		record.RecoveryReturning = false
		return nil
	}
	rollbackAcknowledged := func(status Status) bool {
		return status.ActionID == CommandID(record.ID, "rollback") && status.Error == "" && status.Version == record.Previous && status.Pending == ""
	}
	recovered := func(status Status, since time.Time) error {
		if record.Previous == "" {
			// First-install rollback restores absence, so mesh probes cannot run.
			if !status.Missing || status.Version != "" || status.ObservedAt.IsZero() ||
				now.Sub(status.ObservedAt) > 15*time.Second || status.ObservedAt.Sub(now) > 2*time.Second {
				return errors.New("previous NetBird absence has not been freshly observed")
			}
			return nil
		}
		return r.Healthy(ctx, record.Node, status, since)
	}
	hash := Hash(target)
	if record.Phase == "failed" {
		// Recover the held node even when this pin stays failed or is removed.
		// The completion marker is written only after our fence is released.
		if !record.RecoveryComplete {
			status, err := r.Status(ctx, record.Node)
			// Older journals lack the marker. Require proof of recovery unless
			// this controller explicitly recorded that no agent mutation began.
			if err != nil || status.Pending != "" || status.Error != "" || (record.RollbackRequired == nil || *record.RollbackRequired) && !rollbackAcknowledged(status) {
				return errors.New("previous NetBird rollback is unresolved")
			}
			if err := recovered(status, time.Time{}); err != nil {
				return err
			}
			if err := returnNode(); err != nil {
				return err
			}
			record.RecoveryComplete = true
			if err := r.Save(ctx, record); err != nil {
				return err
			}
		}
		if record.PinHash == hash {
			return fmt.Errorf("NetBird rollout held on %s: %s", record.Node, record.Reason)
		}
	}
	if record.Phase == "" || record.Phase == "done" || record.Phase == "failed" {
		statuses := make(map[string]Status, len(nodes))
		for _, node := range nodes {
			status, err := r.Status(ctx, node)
			if err != nil {
				return err
			}
			if status.Pending != "" || status.Error != "" {
				return fmt.Errorf("NetBird transaction still pending on %s", node)
			}
			statuses[node] = status
		}
		for _, node := range nodes {
			status := statuses[node]
			if status.Version != "" {
				comparison, err := CompareVersions(status.Version, target.Pin.Version)
				if err != nil {
					return err
				}
				if comparison == 0 && status.AppliedTargetHash == hash {
					continue
				}
			}
			if err := r.Preflight(ctx, node); err != nil {
				return err
			}
			record = Record{ID: entityid.New(), Node: node, Previous: status.Version,
				Target: target, PinHash: hash, Phase: "drain", StartedAt: now, Deadline: now.Add(10 * time.Minute)}
			return r.Save(ctx, record)
		}
		return nil
	}
	transition := func(phase string) error { record.Phase = phase; return r.Save(ctx, record) }
	command := func(action string) error {
		return r.Send(ctx, record.Node, Command{ID: CommandID(record.ID, action), Generation: uint64(record.StartedAt.UnixNano()), Transaction: record.ID, Action: action, Target: record.Target})
	}
	rollback := func(reason string) error {
		record.RollbackRequired = new(true)
		record.Reason = reason
		record.Deadline = now.Add(6 * time.Minute)
		return transition("rollback")
	}
	switch record.Phase {
	case "drain":
		if now.After(record.Deadline) {
			record.RollbackRequired = new(false)
			record.Reason = "drain timed out"
			return transition("failed")
		}
		if err := r.Preflight(ctx, record.Node); err != nil {
			return err
		}
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		record.Deadline = currentTime().Add(3 * time.Minute)
		return transition("install")
	case "install":
		if now.After(record.Deadline) {
			return rollback("agent did not acknowledge installation")
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return err
		}
		if status.ActionID == CommandID(record.ID, "install") {
			if status.Error != "" {
				return rollback(status.Error)
			}
			record.Deadline = now.Add(2 * time.Minute)
			return transition("check")
		}
		return command("install")
	case "check":
		status, err := r.Status(ctx, record.Node)
		if err == nil && status.Version == record.Target.Pin.Version && status.Pending == record.ID {
			err = r.Healthy(ctx, record.Node, status, record.StartedAt)
			if err == nil {
				record.Deadline = currentTime().Add(2 * time.Minute)
				return transition("confirm")
			}
		}
		if now.After(record.Deadline) {
			return rollback("new NetBird agent failed mesh health checks")
		}
		return err
	case "confirm":
		if now.After(record.Deadline) {
			return rollback("new NetBird agent was not confirmed")
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return err
		}
		if status.ActionID == CommandID(record.ID, "confirm") && status.Error == "" && status.Pending == "" && status.Version == record.Target.Pin.Version && status.AppliedTargetHash == record.PinHash {
			record.Deadline = now.Add(2 * time.Minute)
			return transition("return")
		}
		return command("confirm")
	case "return":
		failedReturn := func(err error) error {
			if now.After(record.Deadline) {
				return rollback("confirmed NetBird agent failed return health checks")
			}
			return err
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return failedReturn(err)
		}
		if status.Pending != "" || status.Version != record.Target.Pin.Version || status.AppliedTargetHash != record.PinHash || status.ActionID != CommandID(record.ID, "confirm") || status.Error != "" {
			return failedReturn(errors.New("confirmed NetBird transaction changed before return"))
		}
		if err := r.Healthy(ctx, record.Node, status, record.StartedAt); err != nil {
			return failedReturn(err)
		}
		if err := returnNode(); err != nil {
			return failedReturn(err)
		}
		return transition("done")
	case "rollback":
		// Return may have put backends online before an LB health check
		// failed. Re-establish the same fence before restarting the old agent.
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		if err := command("rollback"); err != nil {
			return err
		}
		// Safe re-draining can wait for repaired quorum across many ticks.
		// Allow a full acknowledgment window once the command is sent.
		record.Deadline = currentTime().Add(6 * time.Minute)
		return transition("rollback-check")
	case "rollback-check":
		status, err := r.Status(ctx, record.Node)
		if err == nil && rollbackAcknowledged(status) && recovered(status, record.StartedAt) == nil {
			if err := returnNode(); err != nil {
				if record.RecoveryReturning {
					return err
				}
				if now.After(record.Deadline) {
					record.Reason += "; previous binary failed return health checks (node remains drained)"
					return transition("failed")
				}
				return err
			}
			record.RecoveryComplete = true
			return transition("failed")
		}
		if now.After(record.Deadline) {
			if err := r.Drain(ctx, record.Node); err != nil {
				return err
			}
			record.Reason += "; previous binary did not recover (node remains drained)"
			return transition("failed")
		}
		return command("rollback")
	default:
		return errors.New("unknown NetBird rollout phase")
	}
}

listener.text:
type netbirdTestListener struct {
	net.Listener
	once   sync.Once
	closed func()
}

func (l *netbirdTestListener) Close() error {
	err := l.Listener.Close()
	l.once.Do(l.closed)
	return err
}

	var listener net.Listener
	var bound netip.Addr
	defer func() {
		if listener != nil {
			_ = listener.Close()
		}
	}()
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	last := ""
	for ctx.Err() == nil {
		address := localAddress()
		var err error
		if address != bound {
			if listener != nil {
				_ = listener.Close()
			}
			listener, bound = nil, netip.Addr{}
		}
		if address.IsValid() && listener == nil {
			listener, err = listen(address)
			if err == nil {
				bound = address
			}
		}
		if errors.Is(err, natscell.ErrBridgeClosed) {
			return
		}
		if err != nil && err.Error() != last {
			slog.WarnContext(ctx, "NetBird NATS listener held; retrying", "error", err)
		}
		last = ""
		if err != nil {
			last = err.Error()
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

mesh_dns.text:
type netbirdMeshHosts struct {
	roles   []string
	desired []host.Desired
}

func (h netbirdMeshHosts) ListHosts(context.Context) ([]host.HostStatus, error) {
	status := host.HostStatus{Registration: host.Registration{Node: "joining-node", Roles: h.roles}}
	for _, desired := range h.desired {
		status.Reports = append(status.Reports, host.Report{Node: desired.Node, Role: desired.Role,
			Generation: desired.Generation, State: "running", ObservedAt: time.Now()})
	}
	return []host.HostStatus{status}, nil
}

func (h netbirdMeshHosts) ListDesired(_ context.Context, role string) ([]host.Desired, error) {
	var desired []host.Desired
	for _, entry := range h.desired {
		if entry.Role == role {
			desired = append(desired, entry)
		}
	}
	return desired, nil
}

func netbirdMeshDNS(t *testing.T, address [4]byte) {
	t.Helper()
	listener, err := net.ListenPacket("udp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan struct{})
	go func() {
		defer close(done)
		packet := make([]byte, 4096)
		for {
			size, peer, err := listener.ReadFrom(packet)
			if err != nil {
				return
			}
			var question dnsmessage.Message
			if err := question.Unpack(packet[:size]); err != nil || len(question.Questions) != 1 {
				continue
			}
			response := dnsmessage.Message{Header: dnsmessage.Header{ID: question.ID, Response: true,
				Authoritative: true, RecursionAvailable: true}, Questions: question.Questions}
			if query := question.Questions[0]; query.Type == dnsmessage.TypeA {
				response.Answers = []dnsmessage.Resource{{Header: dnsmessage.ResourceHeader{
					Name: query.Name, Type: dnsmessage.TypeA, Class: dnsmessage.ClassINET, TTL: 1},
					Body: &dnsmessage.AResource{A: address}}}
			}
			wire, err := response.Pack()
			if err == nil {
				_, _ = listener.WriteTo(wire, peer)
			}
		}
	}()
	previous := net.DefaultResolver
	net.DefaultResolver = &net.Resolver{PreferGo: true,
		Dial: func(ctx context.Context, _, _ string) (net.Conn, error) {
			return (&net.Dialer{}).DialContext(ctx, "udp", listener.LocalAddr().String())
		}}
	t.Cleanup(func() {
		net.DefaultResolver = previous
		_ = listener.Close()
		<-done
	})
}

func (n *netbirdRollout) healthy(ctx context.Context, node string, status network.Status, since time.Time) error {
	return n.healthyMesh(ctx, node, status, since, true)
}

func (n *netbirdRollout) healthyMesh(ctx context.Context, node string, status network.Status, since time.Time, verifyLeaderPeer bool) error {
	address, err := netip.ParseAddr(status.IP)
	if !status.Connected || err != nil || !netbirdClientRange.Contains(address) || !strings.HasSuffix(status.DNS, ".nb.ts.internal") || len(status.DNS) > 255 {
		return errors.New("NetBird management, signal, mesh IP and peer DNS name are not ready")
	}
	ctx, cancel := context.WithTimeout(ctx, 8*time.Second)
	defer cancel()
	// The leader's own mesh address is locally routed. Prove a remote peer
	// too, so an isolated leader cannot confirm itself using loopback traffic.
	if verifyLeaderPeer && node == n.services.controllerNode(n.cell, n.cfg.NATS.Instance) {
		_, addresses := n.addresses()
		peers := make([]string, 0, len(addresses))
		for peer := range addresses {
			if peer != node && n.nodes != nil && n.nodes.controllers != nil && n.nodes.controllers(peer) {
				peers = append(peers, peer)
			}
		}
		slices.Sort(peers)
		if len(peers) == 0 {
			return errors.New("NetBird leader has no remote controller peer to verify")
		}
		if err := n.healthyRemotePeer(ctx, peers); err != nil {
			return err
		}
	}
	answers, err := net.DefaultResolver.LookupNetIP(ctx, "ip4", status.DNS)
	if err != nil || !slices.Contains(answers, address) {
		return errors.New("NetBird DNS answer does not contain the peer's mesh IP")
	}
	if reason, err := nodeRolesServing(ctx, n.fence.hosts, node, since); err != nil || reason != "" {
		return fmt.Errorf("node roles are not ready: %s%v", reason, errSuffix(err))
	}
	_, addresses := n.addresses()
	statuses, err := n.fence.hosts.ListHosts(ctx)
	if err != nil {
		return err
	}
	found, probed := false, false
	for _, entry := range statuses {
		if entry.Registration.Node != node {
			continue
		}
		found = true
		for _, role := range entry.Registration.Roles {
			desired, err := n.fence.hosts.ListDesired(ctx, role)
			if err != nil {
				return err
			}
			index := slices.IndexFunc(desired, func(d host.Desired) bool { return d.Node == node && !d.Withdrawn })
			if index < 0 {
				continue
			}
			switch role {
			case tsauth.Role:
				if err := meshReady(ctx, status.IP, tsauth.Port, nil); err != nil {
					return fmt.Errorf("ts-auth over NetBird: %w", err)
				}
				probed = true
			case terrabase.Role:
				profile, err := terrabase.ParseProfile(desired[index].Env)
				if err != nil {
					return err
				}
				pem, err := os.ReadFile(n.cfg.Controller.TerraBaseCACertFile)
				if err != nil {
					return err
				}
				roots := x509.NewCertPool()
				if !roots.AppendCertsFromPEM(pem) {
					return errors.New("invalid TerraBase CA")
				}
				if err := meshReady(ctx, status.IP, profile.ClientPort, &tls.Config{RootCAs: roots, ServerName: addresses[node], MinVersion: tls.VersionTLS12}); err != nil {
					return fmt.Errorf("TerraBase over NetBird: %w", err)
				}
				probed = true
			}
		}
	}
	if !found {
		return errors.New("node has no registered host session")
	}
	if n.nodes != nil && n.nodes.controllers != nil && n.nodes.controllers(node) {
		options := []nats.Option{nats.Timeout(3 * time.Second), nats.NoReconnect(), nats.TLSHandshakeFirst(),
			nats.RootCAs(n.cfg.NATS.TLS.CAFile), nats.ClientCert(n.cfg.NATS.TLS.CertFile, n.cfg.NATS.TLS.KeyFile),
			nats.SetCustomDialer(meshDialer{ctx: ctx, address: net.JoinHostPort(status.IP, "4222")}),
			nats.ErrorHandler(natscell.ErrorHandler)}
		if n.cfg.NATS.CredentialsFile != "" {
			options = append(options, nats.UserCredentials(n.cfg.NATS.CredentialsFile))
		} else {
			option, err := nats.NkeyOptionFromSeed(n.cfg.NATS.NKeySeedFile)
			if err != nil {
				return err
			}
			options = append(options, option)
		}
		conn, err := nats.Connect("tls://"+net.JoinHostPort(addresses[node], "4222"), options...)
		if err != nil {
			return errors.New("authenticated NATS over NetBird is unavailable")
		}
		defer conn.Close()
		if err := conn.FlushWithContext(ctx); err != nil {
			return err
		}
		probed = true
	}
	if !probed {
		return errors.New("NetBird peer has no active service endpoint to verify mesh traffic")
	}
	return nil

